package cn.adc.duration;
import cn.adc.shared.audit.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Audit document boundary, not a duration configuration business implementation. */
class DurationAuditPolicyTest {
 @Test void fullInitialPublicationDocumentAcceptedButTamperedRequestRejected(){
  var before=AuditDocuments.JSON.createObjectNode().put("project_id",1).put("duration_version_no",1).put("project_name","synthetic").put("duration_minutes",30).put("publication_status","DRAFT");before.putNull("published_at");before.putNull("published_by");before.putNull("publication_evidence");var after=before.deepCopy().put("publication_status","CURRENT").put("published_at","2026-11-05T00:00Z").put("published_by","actor");
  var p=after.putObject("publication_evidence").put("schemaVersion",1).put("operationKind","DURATION_PUBLISH").put("requestReference","request").put("canonicalPayloadHash","a".repeat(64)).put("actorReference","actor").put("authorizationScope","GLOBAL_CATALOG").put("reason","synthetic initial publication").put("expectedDraftFingerprint",AuditDocuments.hash(before)).put("recordedAt","2026-11-05T00:00Z");p.putNull("previousCurrentRef");p.putNull("before");p.putObject("after").put("projectId","1").put("versionNo",1).put("projectName","synthetic").put("durationMinutes",30).put("publicationStatus","CURRENT").put("publishedAt","2026-11-05T00:00Z").put("publishedBy","actor");
  var oldEnvelope=AuditDocuments.JSON.createObjectNode();oldEnvelope.set("targetVersion",before);oldEnvelope.putNull("previousCurrentVersion");var newEnvelope=AuditDocuments.JSON.createObjectNode();newEnvelope.set("targetVersion",after);newEnvelope.putNull("previousCurrentVersion");var ref=AuditDocuments.JSON.createObjectNode().put("projectId","1").put("versionNo",1);assertDoesNotThrow(()->AuditDocuments.headquartersOperation("DURATION_PUBLISH",new AuditDocuments.Change(ref,oldEnvelope,newEnvelope,null),"request","a".repeat(64),"actor"));p.put("requestReference","different");assertThrows(IllegalArgumentException.class,()->AuditDocuments.headquartersOperation("DURATION_PUBLISH",new AuditDocuments.Change(ref,oldEnvelope,newEnvelope,null),"request","a".repeat(64),"actor"));
 }
 @Test void invalidOperationCannotCreateForgedOriginalUcCommand(){assertThrows(IllegalArgumentException.class,()->new CommandRecovery.Command("bad-op",null,UUID.randomUUID(),AuditDocuments.JSON.createObjectNode(),Set.of()));}
 @Test void completeLookingDraftCannotMasqueradeAsPublication(){var target=AuditDocuments.JSON.createObjectNode();target.put("project_id",1);target.put("duration_version_no",1);target.put("project_name","synthetic");target.put("duration_minutes",30);target.put("publication_status","DRAFT");target.putNull("published_at");target.putNull("published_by");target.putNull("publication_evidence");var env=AuditDocuments.JSON.createObjectNode();env.set("targetVersion",target);env.putNull("previousCurrentVersion");var ref=AuditDocuments.JSON.createObjectNode().put("projectId","1").put("versionNo",1);var change=new AuditDocuments.Change(ref,env,env,null);assertThrows(IllegalArgumentException.class,()->AuditDocuments.headquartersOperation("DURATION_PUBLISH",change,"request","a".repeat(64),"actor"));assertDoesNotThrow(()->AuditDocuments.headquartersOperation("DURATION_DRAFT_EDIT",change,"request","a".repeat(64),"actor"));}
 @Test void nullOrEmptyBeforeAfterIsNotSuccessEvidence(){assertThrows(IllegalArgumentException.class,()->AuditDocuments.headquartersChange(new AuditDocuments.Change(null,null,null,null)));}
}
